interface Category {
  slug: string;
  name: string;
  image: string;
}

const baseUrl = import.meta.env.BASE_URL;

function createCategoryCard(category: Category): HTMLLIElement {
  const item = document.createElement('li');
  const link = document.createElement('a');
  const image = document.createElement('img');
  const name = document.createElement('span');

  item.className = 'menu__category';
  link.className = 'menu__category-link';
  link.href = `${baseUrl}menu/?category=${encodeURIComponent(category.slug)}`;
  image.className = 'menu__category-image';
  image.src = `${baseUrl}${category.image}`;
  image.alt = '';
  name.className = 'menu__category-name';
  name.textContent = category.name;

  link.append(image, name);
  item.append(link);

  return item;
}

export async function menu(): Promise<void> {
  const categoriesList = document.querySelector<HTMLUListElement>('.menu__categories');
  const status = document.querySelector<HTMLParagraphElement>('.menu__status');

  if (!categoriesList || !status) return;

  try {
    const response = await fetch(`${baseUrl}categories.json`);

    if (!response.ok) {
      throw new Error(`Не удалось загрузить категории: ${response.status}`);
    }

    const categories = (await response.json()) as Category[];
    categoriesList.append(...categories.map(createCategoryCard));
    status.remove();
  } catch (error) {
    status.textContent = 'Не удалось загрузить категории. Попробуйте обновить страницу.';
    console.error(error);
  }
}
